window.HOEREN_TESTS[41] = {"id":"geburtstag-und-geschenke","name":"Geburtstag und Geschenke","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Lisa, hier ist Anna. Der Geburtstag von Tom ist nächste Woche. Wir wollen ein Geschenk zusammen kaufen — was meinst du? Tom liebt ja Bücher. Oder vielleicht ein Konzert-Ticket? Eine CD hat er schon so viele. Eigentlich am besten Bücher, das ist sicher. Ruf zurück, dann gehen wir shoppen.","gender":"f","q":"Was kaufen sie wahrscheinlich?","opts":["Ein Buch.","Ein Konzert-Ticket.","Eine CD."],"correct":0},{"transcript":"Hi Markus, hier ist Sara. Mein Geburtstag ist am Samstag. Ich mache eine Party bei mir zu Hause, ab 19 Uhr. Bring bitte etwas zum Trinken mit, Essen mache ich selbst. Geschenke braucht ihr nicht mitbringen. Komm in normaler Kleidung, kein Anzug. Lass mich wissen, ob du kommst.","gender":"f","q":"Was soll Markus mitbringen?","opts":["Etwas zum Trinken.","Etwas zum Essen.","Ein Geschenk."],"correct":0},{"transcript":"Achtung, eine Erinnerung: Klein-Max wird am Sonntag fünf Jahre alt! Wir feiern im Restaurant Sonnenblume um 14 Uhr, die Feier dauert bis 17 Uhr. Kinder spielen draußen im Garten. Bitte keine Geschenke aus Plastik — Max hat schon zu viele Spielsachen. Bücher oder Kleidung sind willkommen. Parkplätze gibt es hinter dem Restaurant.","gender":"m","q":"Was möchten die Eltern nicht?","opts":["Bücher.","Plastik-Spielzeug.","Kleidung."],"correct":1},{"transcript":"Liebe Tante Else, hier ist Anna. Dein Geburtstag — 70 Jahre, große Sache! Nicht 60 und noch nicht 80, genau richtig zum Feiern! Wir kommen alle: ich, Markus, die Kinder, sogar Onkel Hans aus Hamburg. Brauchst du Hilfe mit dem Essen? Wir können gerne kochen. Ruf an, sag was nötig ist. Bis Samstag, freue mich!","gender":"f","q":"Wie alt wird Tante Else?","opts":["60 Jahre.","80 Jahre.","70 Jahre."],"correct":2},{"transcript":"Hallo Lisa, hier ist Mama. Hey, Papa hat doch Geburtstag morgen. Was schenken wir ihm? Eine Krawatte hat er schon zu viele. Ein Buch hat er schon selber gekauft. Ich denke, eine schöne Uhr wäre perfekt. Im Geschäft in der Stadt gibt es schöne Uhren. Was meinst du? Ruf bitte zurück.","gender":"f","q":"Was schlägt Mama vor?","opts":["Eine Krawatte.","Eine Uhr.","Ein Buch."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer schenkt was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Annas großer Geburtstag ist schon an diesem Samstag."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Noch nicht alle Geschenke liegen bereit. Wir fragen kurz nach."},{"speaker":"Lukas","gender":"m","text":"Von mir gibt es Schmuck. Eine silberne Kette passt gut zu ihr."},{"speaker":"Lisa","gender":"f","text":"Die Kette wird ihr wirklich gut gefallen. Du kennst ihren Geschmack."},{"speaker":"Lukas","gender":"m","text":"Bringt noch jemand eine CD mit?"},{"speaker":"Lisa","gender":"f","text":"Nein. Eine CD schenkt keiner."},{"speaker":"Lukas","gender":"m","text":"Dein Paket ist flach und ziemlich schwer in der Hand."},{"speaker":"Lisa","gender":"f","text":"Ich habe ein Buch eingepackt. Sie liest abends gern im Sessel."},{"speaker":"Lukas","gender":"m","text":"Tom war gestern lange drüben in der Parfümerie."},{"speaker":"Lisa","gender":"f","text":"Tom kommt mit Parfüm vorbei. Der Duft ist leicht und frisch."},{"speaker":"Lukas","gender":"m","text":"Sara hat für den Morgen einen Strauß bestellt."},{"speaker":"Lisa","gender":"f","text":"Sara bringt Blumen mit. Rote Rosen kommen schon früh an."},{"speaker":"Lukas","gender":"m","text":"Sollen wir auch Wein mitbringen?"},{"speaker":"Lisa","gender":"f","text":"Nein. Wein bringen wir auch nicht mit."},{"speaker":"Lukas","gender":"m","text":"Tim will zum Kaffee unbedingt etwas Süßes dabei haben."},{"speaker":"Lisa","gender":"f","text":"Tim hat Schokolade gekauft. Die Tafel ist dunkel und groß."},{"speaker":"Lukas","gender":"m","text":"Dann packen wir die Sachen am Freitagabend zusammen ein."},{"speaker":"Lisa","gender":"f","text":"Ich hole noch Papier und eine goldene Schleife."}],"options":[{"letter":"a","text":"CD"},{"letter":"b","text":"Schmuck"},{"letter":"c","text":"Geld"},{"letter":"d","text":"Wein"},{"letter":"e","text":"Blumen"},{"letter":"f","text":"Parfüm"},{"letter":"g","text":"Konzertkarte"},{"letter":"h","text":"Buch"},{"letter":"i","text":"Schokolade"}],"items":[{"person":"Lukas","correct":"b"},{"person":"Lisa","correct":"h"},{"person":"Tom","correct":"f"},{"person":"Sara","correct":"e"},{"person":"Tim","correct":"i"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag! Ich suche ein Geschenk für meine 16-jährige Tochter."},{"speaker":"Verkäufer","gender":"m","text":"Wie wäre es mit Schmuck? Oder ein schönes Parfüm?"},{"speaker":"Kundin","gender":"f","text":"Schmuck hat sie schon genug. Und Parfüm mag sie gar nicht. Vielleicht ein nettes Top?"},{"speaker":"Verkäufer","gender":"m","text":"Gute Idee! Wir haben tolle neue Tops da. Welche Größe?"},{"speaker":"Kundin","gender":"f","text":"Größe 38, bitte. Das Top gefällt ihr sicher."}],"q":"Was kauft die Mutter?","opts":["Schmuck.","Ein Top.","Parfüm."],"correct":1},{"lines":[{"speaker":"Sohn","gender":"m","text":"Mama, was wünschst du dir zum Geburtstag? Ein Geschenk?"},{"speaker":"Mutter","gender":"f","text":"Nichts Materielles, mein Schatz. Lieber ein gemeinsames Essen im Restaurant."},{"speaker":"Sohn","gender":"m","text":"Oder ich koche selbst für dich? Das wäre billiger."},{"speaker":"Mutter","gender":"f","text":"Nein, du kochst sowieso nie, das dauert zu lange. Gehen wir ins Restaurant!"},{"speaker":"Sohn","gender":"m","text":"Gut, dann lade ich dich am Samstag ins Restaurant ein."}],"q":"Was wünscht sich die Mutter?","opts":["Gemeinsames Essen im Restaurant.","Ein Geschenk.","Selbst gekochtes Essen."],"correct":0},{"lines":[{"speaker":"Vater","gender":"m","text":"Lukas wird 10 Jahre alt. Welchen Kuchen backen wir?"},{"speaker":"Mutter","gender":"f","text":"Schokolade oder Erdbeere? Was meinst du?"},{"speaker":"Vater","gender":"m","text":"Schokolade hatte er letztes Jahr. Lieber etwas Neues."},{"speaker":"Mutter","gender":"f","text":"Vanille mag er nicht so. Dann nehmen wir Erdbeere, einverstanden?"},{"speaker":"Vater","gender":"m","text":"Einverstanden! Ich kaufe morgen frische Erdbeeren auf dem Markt, und wir backen zusammen."}],"q":"Welcher Kuchen wird es?","opts":["Schokolade.","Erdbeere.","Vanille."],"correct":1},{"lines":[{"speaker":"Lisa","gender":"f","text":"Tom, danke für die Einladung zur Party am Samstag!"},{"speaker":"Tom","gender":"m","text":"Bitte! Kommst du? Es wird lustig."},{"speaker":"Lisa","gender":"f","text":"Eigentlich ja, aber meine Mutter ist plötzlich krank geworden."},{"speaker":"Tom","gender":"m","text":"Oh, das tut mir leid. Dann kommst du später nach, oder?"},{"speaker":"Lisa","gender":"f","text":"Nein, das geht leider nicht. Aber ich schicke dein Geschenk per Post, versprochen!"},{"speaker":"Tom","gender":"m","text":"Verstehe, kein Problem. Gute Besserung für deine Mutter!"}],"q":"Was macht Lisa?","opts":["Kommt zur Party.","Kommt später.","Schickt Geschenk per Post."],"correct":2},{"lines":[{"speaker":"Anna","gender":"f","text":"Wo machen wir Saras Geburtstag? Hast du eine Idee?"},{"speaker":"Markus","gender":"m","text":"Im Restaurant? Oder lieber zu Hause bei uns?"},{"speaker":"Anna","gender":"f","text":"Das Restaurant ist zu teuer, und zu Hause ist zu wenig Platz."},{"speaker":"Markus","gender":"m","text":"Dann machen wir ein Picknick im Park! Das ist kostenlos und draußen."},{"speaker":"Anna","gender":"f","text":"Gute Idee! Im Park, wenn das Wetter gut ist. Ich bringe Kuchen mit."}],"q":"Wo wird die Feier sein?","opts":["Restaurant.","Zu Hause.","Im Park."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Klingmann, einer Party-Planerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Klingmann, Sie planen seit 15 Jahren Geburtstagspartys. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Klingmann","gender":"f","text":"Ich habe schon als Studentin gerne Partys für Freunde organisiert. Dann hat mich eine Bekannte gefragt — die Tochter wurde 18, große Party. Ich habe alles geplant, war ein Erfolg. Daraus wurde mein Geschäft."},{"speaker":"Reporter","gender":"m","text":"Welche Partys planen Sie am häufigsten?"},{"speaker":"Klingmann","gender":"f","text":"Kinder-Geburtstage am meisten, etwa die Hälfte. Dann 18. und 50. Geburtstage — runde Zahlen. Hochzeiten mache ich auch, aber das ist anders, viel mehr Stress."},{"speaker":"Reporter","gender":"m","text":"Was kostet eine Party im Durchschnitt?"},{"speaker":"Klingmann","gender":"f","text":"Sehr unterschiedlich, kleine Kinder-Party 300 Euro. Größere Erwachsenen-Feiern 2000 bis 5000 Euro. Manche Kunden geben aber auch 10.000 Euro aus — sehr exklusiv. Das ist aber selten."},{"speaker":"Reporter","gender":"m","text":"Was ist der häufigste Wunsch?"},{"speaker":"Klingmann","gender":"f","text":"Ein Thema — Märchen für Kinder, 80er-Jahre für Erwachsene, irgendwas Spezielles. Standard-Party will keiner mehr. Auch DIY-Elemente sind beliebt — Bastel-Tisch für Kinder, zum Beispiel."},{"speaker":"Reporter","gender":"m","text":"Wenn Sie selbst Geburtstag haben? Planen Sie da eine große Feier?"},{"speaker":"Klingmann","gender":"f","text":"Nein, wirklich nicht. Keine große Feier, keine 100 Gäste. Beruflich habe ich genug Partys. Privat bin ich mit Familie im Restaurant — einfach. Wir essen, lachen, mehr nicht."}],"items":[{"q":"Frau Klingmann hat mit Studenten-Partys angefangen.","correct":"ja"},{"q":"Die Hälfte ihrer Partys sind Hochzeiten.","correct":"nein"},{"q":"Es gibt Kunden, die 10.000 Euro für eine Party ausgeben.","correct":"ja"},{"q":"Standard-Partys ohne Thema sind heute am beliebtesten.","correct":"nein"},{"q":"An ihrem eigenen Geburtstag plant sie keine große Feier.","correct":"ja"}]}]};
